<#
.SYNOPSIS
3£Windows: one tray menu for three-finger drag, Clicks keyboard, PowerToys,
automatic light/dark mode and dynamic wallpaper.
.NOTES
Phone/watch trackpad is optional and off at startup. Left-click the tray icon
and scan its QR code on iPhone. Email the same link to open it on Apple Watch.
The devices use the same trusted Wi-Fi; the trackpad needs no internet.
Missing Wi-Fi or a disconnected device never stops other suite components.
.DESCRIPTION
Portable single-file installer. The application and keyboard rules are embedded.
Copy this .ps1 alone to another Windows PC. Internet is needed to install signed
third-party dependencies not already present. Requires Windows 10 1809+ / 11,
administrator approval, and a Precision Touchpad for dragging. Clicks mapping on x64
uses a device-specific filter; no class-wide keyboard or mouse filter is installed.
Setup preserves personal wallpaper and drag preferences. Existing Edy startup
tasks are migrated to 3£Windows. Updates use only Ezodis/3E windows-v releases.
.PARAMETER Install
Reinstall explicitly. Without switches, an existing installation starts the suite.
.PARAMETER Down
Remove 3£Windows and its startup tasks; restore backed-up input preferences.
Third-party PowerToys, WinDynamicDesktop and .NET installations are retained.
.PARAMETER KeyboardOnly
Apply only the left Alt/Ctrl swap (or remove it with -Down); restart required.
.PARAMETER RepairKeyboard
Restore the Clicks-only Command/Ctrl mapping and double-tap voice shortcut.
.PARAMETER AppOnly
Update the app and startup integration without changing keyboard, touchpad or
PowerToys module preferences. Used by the built-in updater.
#>
[CmdletBinding()]
param([switch]$Down, [switch]$KeyboardOnly, [switch]$AppOnly, [switch]$Install, [switch]$RepairKeyboard)
$ErrorActionPreference = 'Stop'
$Version = '1.0.15'
# Existing installations launch without rerunning setup. Use -Install to reinstall.
$EmbeddedLauncher = @'
[CmdletBinding()]
param([switch]$Wait)
$ErrorActionPreference = 'Stop'
$root = Join-Path $env:ProgramFiles '3EWindows'
$app = Join-Path $root '3£Windows.exe'
if (-not (Test-Path -LiteralPath $app)) { throw 'Install 3£Windows before launching it.' }
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class ThreeEPermission {
 [DllImport("advapi32.dll",SetLastError=true)] static extern bool OpenProcessToken(IntPtr p,uint access,out IntPtr token);
 [DllImport("advapi32.dll",SetLastError=true)] static extern bool GetTokenInformation(IntPtr t,int cls,out int info,int size,out int used);
 [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
 [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
 public static bool Elevated(int pid) { IntPtr p=OpenProcess(0x1000,false,pid); if(p==IntPtr.Zero) throw new System.ComponentModel.Win32Exception(); try { IntPtr t; if(!OpenProcessToken(p,8,out t)) throw new System.ComponentModel.Win32Exception(); try { int v,n; if(!GetTokenInformation(t,20,out v,4,out n)) throw new System.ComponentModel.Win32Exception(); return v!=0; } finally {CloseHandle(t);} } finally {CloseHandle(p);} }
}
"@
$sid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
$gate = [Threading.Mutex]::new($false, ('Local\3EWindows-Launch-' + $sid))
$locked = $false
try {
    try { $locked = $gate.WaitOne(30000) } catch [Threading.AbandonedMutexException] { $locked = $true }
    if (-not $locked) { throw 'Another 3£Windows launch is still awaiting approval.' }
    $running = @(Get-Process -Name '3£Windows' -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId })
    $process = $running | Where-Object { [ThreeEPermission]::Elevated($_.Id) } | Select-Object -First 1
    if (-not $process) {
        # One elevation starts the tray app and all input engines together.
        foreach ($name in @('3£Windows','3EWindows.Keyboard','PowerToys','PowerToys.KeyboardManagerEngine')) {
            Get-Process -Name $name -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq (Get-Process -Id $PID).SessionId } | Stop-Process -Force
        }
        $process = Start-Process -FilePath $app -WorkingDirectory $root -Verb RunAs -WindowStyle Hidden -PassThru
        Start-Sleep -Seconds 2
        if ((-not (Get-Process -Id $process.Id -ErrorAction SilentlyContinue)) -or -not [ThreeEPermission]::Elevated($process.Id)) { throw 'Windows did not grant administrator permission to 3£Windows.' }
    }
} finally {
    if ($locked) { $gate.ReleaseMutex() }
    $gate.Dispose()
}
if ($Wait -and $process) { while (Get-Process -Id $process.Id -ErrorAction SilentlyContinue) { Start-Sleep -Seconds 2 } }
'@
# A current installation launches directly. A newer portable file updates the
# app and existing Clicks components without resetting personal input settings.
if (-not ($Down -or $KeyboardOnly -or $AppOnly -or $Install -or $RepairKeyboard) -and (Test-Path -LiteralPath (Join-Path $env:ProgramFiles '3EWindows\3£Windows.exe'))) {
    $assembly = Join-Path $env:ProgramFiles '3EWindows\ThreeEWindows.dll'
    # Keyboard helper fixes can ship without changing the main app version.
    $accentExe = Join-Path $env:ProgramFiles '3EWindows\Keyboard\ClicksAccents.exe'
    $accentCurrent = -not (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA '3EWindows\ClicksDeviceMapping.json')) -or
        ((Test-Path -LiteralPath $accentExe) -and (Get-FileHash -LiteralPath $accentExe -Algorithm SHA256).Hash -eq '0BDAD8DC17CE7A32AB3C2AC3E0E373AC2061E23C3D4CFEEA9FA41813036F8BB9')
    if ($accentCurrent -and (Test-Path -LiteralPath $assembly) -and [Diagnostics.FileVersionInfo]::GetVersionInfo($assembly).ProductVersion.Split('+')[0] -eq $Version) {
        & ([scriptblock]::Create($EmbeddedLauncher))
        exit
    }
    $AppOnly = $true
}

$EmbeddedPowerToysKeyboardConfig = @'
